        instruction: "Ihr Freund Jonas möchte am Samstag mit Ihnen Fußball spielen. Sie sind erkältet. Schreiben Sie ihm eine SMS (20–30 Wörter). Schreiben Sie zu allen drei Punkten: Grund – Absage – anderer Termin.",
        instructionTr: {
          en: "Your friend Jonas wants to play football with you on Saturday. You have a cold. Write him a text message (20–30 words). Write about all three points: reason – cancelling – another date.",
          fr: "Votre ami Jonas veut jouer au football avec vous samedi. Vous êtes enrhumé(e). Écrivez-lui un SMS (20–30 mots). Traitez les trois points : raison – annulation – autre date.",
        },
        points: [
          { id: "p1", de: "Grund (erkältet)", tr: { en: "Reason (you have a cold)", fr: "Raison (vous êtes enrhumé(e))" }, keywords: ["erkältet", "krank", "fieber", "husten", "schnupfen"] },
          { id: "p2", de: "Absage für Samstag", tr: { en: "Cancel Saturday", fr: "Annuler samedi" }, keywords: ["kann", "leider", "nicht spielen", "absag"] },
          { id: "p3", de: "Vorschlag für einen anderen Termin", tr: { en: "Suggestion for another date", fr: "Proposition d’une autre date" }, keywords: ["nächste", "woche", "mittwoch", "sonntag", "stattdessen"] },
        ],
        minWords: 20, maxWords: 30,
